/**
 * server/scripts/cleanup-test-data.js
 *
 * Scans MongoDB for test artifacts generated by automated or manual testing.
 *
 * Matching patterns:
 *   - "Hospital Alpha 17*"
 *   - "*Donor 17*"
 *   - "Atlas Test User"
 *   - Names/emails containing a 13-digit Unix timestamp (e.g. from Date.now())
 *
 * Protected whitelist (NEVER touched):
 *   - City General Hospital / City General Emergency Hospital
 *   - Admin account (admin@lifelink.com, accountType === 'admin')
 *   - Demo accounts: donor1, hospital, admin, Alex Rivera, Sarah Connor,
 *     Priya Sharma, Marcus Vance, Elena Rostova, David Kim
 *
 * Usage:
 *   node server/scripts/cleanup-test-data.js           # DRY RUN (lists only, deletes nothing)
 *   node server/scripts/cleanup-test-data.js --confirm # Permanently deletes matched test records
 */

const path = require('path');
const mongoose = require('mongoose');
require('dotenv').config({ path: path.join(__dirname, '../.env') });

const User = require('../src/models/User');
const Hospital = require('../src/models/Hospital');
const DonorProfile = require('../src/models/DonorProfile');
const BloodRequest = require('../src/models/BloodRequest');
const Donation = require('../src/models/Donation');

// Whitelisted identities that MUST NEVER be deleted
const WHITELIST_EMAILS = new Set([
  'admin@lifelink.com',
  'hospital@lifelink.com',
  'donor1@lifelink.com',
  'recipient@lifelink.com',
  'user@lifelink.com',
  'donor2@lifelink.com',
  'donor3@lifelink.com',
]);

const WHITELIST_NAME_KEYWORDS = [
  'city general',
  'system admin',
  'alex rivera',
  'sarah connor',
  'priya sharma',
  'marcus vance',
  'elena rostova',
  'david kim',
  'demo',
];

function isWhitelisted(item) {
  if (!item) return false;
  if (item.accountType === 'admin') return true;

  const email = (item.email || '').toLowerCase().trim();
  if (WHITELIST_EMAILS.has(email)) return true;

  const name = (item.name || item.patientName || item.requesterName || '').toLowerCase().trim();
  for (const keyword of WHITELIST_NAME_KEYWORDS) {
    if (name.includes(keyword)) return true;
  }

  return false;
}

function matchesTestPattern(str) {
  if (!str || typeof str !== 'string') return false;

  // 1. "Hospital Alpha 17*"
  if (/Hospital\s+Alpha\s+17/i.test(str)) return true;

  // 2. "*Donor 17*"
  if (/Donor.*17\d{8,}/i.test(str) || /Donor\s+17/i.test(str)) return true;

  // 3. "Atlas Test User"
  if (/Atlas\s+Test\s+User/i.test(str)) return true;

  // 4. Any name/string containing a 13-digit timestamp (e.g. 1700000000000)
  if (/\b\d{13}\b/.test(str) || /\d{13}/.test(str)) return true;

  return false;
}

async function run() {
  const isConfirmed = process.argv.includes('--confirm');

  console.log('===============================================================');
  console.log(` 🧹 LifeLink Test Data Cleanup Utility [${isConfirmed ? 'EXECUTE MODE' : 'DRY RUN ONLY'}]`);
  console.log('===============================================================\n');

  if (!process.env.MONGODB_URI) {
    console.error('❌ MONGODB_URI not found in environment. Ensure server/.env exists.');
    process.exit(1);
  }

  await mongoose.connect(process.env.MONGODB_URI);
  console.log('Connected to MongoDB database.\n');

  // 1. Identify Test Users
  const allUsers = await User.find().lean();
  const matchedUsers = allUsers.filter(u => {
    if (isWhitelisted(u)) return false;
    return matchesTestPattern(u.name) || matchesTestPattern(u.email);
  });
  const matchedUserIds = matchedUsers.map(u => u._id.toString());
  const matchedUserIdSet = new Set(matchedUserIds);

  // 2. Identify Test Hospitals
  const allHospitals = await Hospital.find().lean();
  const matchedHospitals = allHospitals.filter(h => {
    if (isWhitelisted(h)) return false;
    const userMatches = h.user && matchedUserIdSet.has(h.user.toString());
    return matchesTestPattern(h.name) || userMatches;
  });
  const matchedHospitalIds = matchedHospitals.map(h => h._id.toString());
  const matchedHospitalIdSet = new Set(matchedHospitalIds);

  // 3. Identify Test Donor Profiles
  const allProfiles = await DonorProfile.find().populate('user', 'name email').lean();
  const matchedProfiles = allProfiles.filter(p => {
    if (isWhitelisted(p.user)) return false;
    const userMatches = p.user && matchedUserIdSet.has((p.user._id || p.user).toString());
    const addressMatches = matchesTestPattern(p.address);
    return userMatches || addressMatches;
  });
  const matchedProfileIds = matchedProfiles.map(p => p._id.toString());

  // 4. Identify Test Blood Requests
  const allRequests = await BloodRequest.find().lean();
  const matchedRequests = allRequests.filter(r => {
    if (isWhitelisted(r)) return false;
    const requesterMatches = r.requester && matchedUserIdSet.has(r.requester.toString());
    const targetHospMatches = r.targetHospital && matchedHospitalIdSet.has(r.targetHospital.toString());
    const nameMatches = matchesTestPattern(r.patientName) || matchesTestPattern(r.requesterName);
    return requesterMatches || targetHospMatches || nameMatches;
  });
  const matchedRequestIds = matchedRequests.map(r => r._id.toString());
  const matchedRequestIdSet = new Set(matchedRequestIds);

  // 5. Identify Test Donations
  const allDonations = await Donation.find().lean();
  const matchedDonations = allDonations.filter(d => {
    const donorMatches = d.donor && matchedUserIdSet.has(d.donor.toString());
    const reqMatches = d.request && matchedRequestIdSet.has(d.request.toString());
    return donorMatches || reqMatches;
  });
  const matchedDonationIds = matchedDonations.map(d => d._id.toString());

  // Print results
  console.log('─── Identified Test Records ────────────────────────────────────');
  console.log(`• Users:           ${matchedUsers.length}`);
  matchedUsers.forEach(u => {
    console.log(`   - [User]     ID: ${u._id} | Name: "${u.name}" | Email: ${u.email} | Role: ${u.accountType}`);
  });

  console.log(`\n• Hospitals:       ${matchedHospitals.length}`);
  matchedHospitals.forEach(h => {
    console.log(`   - [Hospital] ID: ${h._id} | Name: "${h.name}" | Phone: ${h.phone || 'N/A'}`);
  });

  console.log(`\n• Donor Profiles:  ${matchedProfiles.length}`);
  matchedProfiles.forEach(p => {
    const userName = p.user?.name || 'N/A';
    console.log(`   - [Profile]  ID: ${p._id} | User: "${userName}" | Group: ${p.bloodGroup}`);
  });

  console.log(`\n• Blood Requests:  ${matchedRequests.length}`);
  matchedRequests.forEach(r => {
    console.log(`   - [Request]  ID: ${r._id} | Patient: "${r.patientName}" | Group: ${r.bloodGroup} | Status: ${r.status}`);
  });

  console.log(`\n• Donations:       ${matchedDonations.length}`);
  matchedDonations.forEach(d => {
    console.log(`   - [Donation] ID: ${d._id} | Status: ${d.status}`);
  });

  const totalMatches =
    matchedUsers.length +
    matchedHospitals.length +
    matchedProfiles.length +
    matchedRequests.length +
    matchedDonations.length;

  console.log('\n────────────────────────────────────────────────────────────────');
  console.log(`Total test items matching pattern: ${totalMatches}`);
  console.log('────────────────────────────────────────────────────────────────\n');

  if (!isConfirmed) {
    console.log('⚠️  DRY RUN COMPLETED.');
    console.log('   NO records were modified or deleted.');
    console.log('   To permanently remove the records listed above, run:');
    console.log('   node server/scripts/cleanup-test-data.js --confirm\n');
    await mongoose.disconnect();
    return;
  }

  // Deletion phase (only when --confirm is provided)
  console.log('🚀 DELETION IN PROGRESS (--confirm received)...');

  let deletedDonations = 0;
  let deletedRequests = 0;
  let deletedProfiles = 0;
  let deletedHospitals = 0;
  let deletedUsers = 0;

  if (matchedDonationIds.length > 0) {
    const res = await Donation.deleteMany({ _id: { $in: matchedDonationIds } });
    deletedDonations = res.deletedCount;
  }

  if (matchedRequestIds.length > 0) {
    const res = await BloodRequest.deleteMany({ _id: { $in: matchedRequestIds } });
    deletedRequests = res.deletedCount;
  }

  if (matchedProfileIds.length > 0) {
    const res = await DonorProfile.deleteMany({ _id: { $in: matchedProfileIds } });
    deletedProfiles = res.deletedCount;
  }

  if (matchedHospitalIds.length > 0) {
    const res = await Hospital.deleteMany({ _id: { $in: matchedHospitalIds } });
    deletedHospitals = res.deletedCount;
  }

  if (matchedUserIds.length > 0) {
    const res = await User.deleteMany({ _id: { $in: matchedUserIds } });
    deletedUsers = res.deletedCount;
  }

  console.log('✅ Cleanup successful:');
  console.log(`   - Deleted ${deletedDonations} test donation(s)`);
  console.log(`   - Deleted ${deletedRequests} test blood request(s)`);
  console.log(`   - Deleted ${deletedProfiles} test donor profile(s)`);
  console.log(`   - Deleted ${deletedHospitals} test hospital(s)`);
  console.log(`   - Deleted ${deletedUsers} test user(s)`);
  console.log('Protected demo accounts and City General Hospital were preserved.\n');

  await mongoose.disconnect();
}

run().catch((err) => {
  console.error('Fatal cleanup error:', err);
  process.exit(1);
});
